int main(int argc,char** argv){try{if(argc<2){std::cerr<<"usage: group_query48u fixture.json [report.json] [--differential-only]\n";return 2;}std::fesetround(FE_TONEAREST);std::ifstream file(argv[1]);Json packet;file>>packet;if(packet.at("schema")!=1||packet.at("cases").empty())throw std::runtime_error("invalid original group fixture packet");const Json* base=nullptr;const Json* compact=nullptr;std::map<std::string,std::size_t> partitions;for(const auto& row:packet.at("cases")){++partitions[row.value("native_scope",std::string("complete"))];differential(packet,row);differential(packet,row,1);if(row.at("name")=="shared-compact-shape-4")compact=&row;if(!base&&expectedStatus(row)==Status::Complete&&row.at("groups").size()==1&&row.at("outer_order").size()==1&&row.at("groups")[0].at("members").size()>=2){bool all=true;for(const auto& c:row.at("candidates"))all=all&&c.at("shape_tag")==0;if(all)base=&row;}}if(!base)throw std::runtime_error("no multi-member complete group baseline");Json perf=nullptr;if(!(argc>3&&std::string(argv[3])=="--differential-only")){safety(packet,*base);hintSafety(packet,*base);if(compact)compactSafety(packet,*compact);perf=benchmark(packet,*base);}check(differentialCases+unsupportedCases==packet.at("cases").size()*2,"every original case explicitly classified in both validation modes");check(allocations()==0,"all guarded calls allocate zero times");auto report=accounting();report["fixture_cases"]=packet.at("cases").size();report["validation_modes"]=2;report["partitions"]=partitions;report["benchmark"]=perf;report["scope"]="source-executed122660 outer groups; caller-owned serial native finite binary32 projection; no live-world or console FPS claim";if(argc>2){std::ofstream out(argv[2]);out<<report.dump(2)<<'\n';}std::cout<<report.dump()<<'\n';return failures?1:0;}catch(const std::exception& e){watching=false;std::cerr<<label<<": harness error: "<<e.what()<<'\n';return 2;}}
